const valid = value => typeof value === 'string' && /^[A-Za-z0-9_-]{1,64}$/.test(value);
const event = $input.first().json;
const workflowId = String(event.workflow?.id ?? '');
const executionId = String(event.execution?.id ?? '');
if (!valid(workflowId) || !valid(executionId)) return [];
return [{ json: { workflowId, executionId } }];

const ids = $('Select staging failure IDs').first().json;
const raw = $input.first().json;
const revision = raw.workflowVersionId ?? raw.workflowData?.versionId;
const result = raw.data?.resultData;
const runData = result?.runData;
const workflowNodes = raw.workflowData?.nodes;
const nodes = Array.isArray(workflowNodes) ? workflowNodes.map(node => node?.name ?? null) : null;
const matches = String(raw.id ?? '') === ids.executionId &&
  String(raw.workflowId ?? '') === ids.workflowId && raw.status === 'error';
const delivery = {
  environment: 'staging',
  ...ids,
  execution: matches ? {
    id: ids.executionId,
    workflowId: ids.workflowId,
    revision,
    status: raw.status,
    nodes,
    executed: runData && typeof runData === 'object' && !Array.isArray(runData) ? Object.keys(runData) : null,
    failedNode: result?.lastNodeExecuted ?? null,
  } : null,
};
const deliveryId = String($execution.id ?? '');
if (!/^[A-Za-z0-9_-]{1,64}$/.test(deliveryId)) throw new Error('Expected a saved delivery ID.');
const fileName = `failure-${ids.workflowId}-${ids.executionId}-${deliveryId}.json`;
return [{
  json: { fileName },
  binary: { data: {
    data: Buffer.from(JSON.stringify(delivery), 'utf8').toString('base64'),
    mimeType: 'application/json',
    fileName,
  } },
}];
